import * as THREE from 'three';
import {goodSymbol} from './economy-map-core.js?v=43.1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const compact=n=>n.toLocaleString('pt-BR',{maximumFractionDigits:n>=100?0:1});
export function createEconomicMapOverlay({D,world,point,camera,controls,relief,provinceAt,onMarket,onProvince}){
 const group=new THREE.Group();world.add(group);const labels=document.createElement('div');labels.id='economicMapLabels';document.body.append(labels);let mode='',data=null,entries=[],lastTick=0,leaders=null;
 const projected=new THREE.Vector3();
 function clear(){for(const o of group.children)o.traverse(n=>{n.geometry?.dispose();if(n.material)n.material.dispose();});group.clear();labels.replaceChildren();leaders=document.createElementNS('http://www.w3.org/2000/svg','svg');leaders.classList.add('econLabelLeaders');labels.append(leaders);entries=[];}
 function label(xy,html,kind,weight,action,title){const button=document.createElement('button');button.className='econMapBadge '+kind;button.innerHTML=html;button.title=title||'';button.onclick=e=>{e.stopPropagation();action();};labels.append(button);entries.push({button,anchor:point(xy[0],xy[1],kind==='market'?15:9),kind,weight});}
 function boundaries(field){const positions=[],g=D.grid;for(const c of D.cells){if(c.h<20||c.state===17||!field(c.i))continue;const col=c.i%g.columns,row=Math.floor(c.i/g.columns);for(const [other,a,b]of [[col<g.columns-1?c.i+1:-1,[(col+1)*g.stepX,row*g.stepY],[(col+1)*g.stepX,(row+1)*g.stepY]],[row<g.rows-1?c.i+g.columns:-1,[col*g.stepX,(row+1)*g.stepY],[(col+1)*g.stepX,(row+1)*g.stepY]]]){if(other<0||D.cells[other].h<20||field(other)===field(c.i))continue;positions.push(...point(...a,3).toArray(),...point(...b,3).toArray());}}
  const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));const line=new THREE.LineSegments(geo,new THREE.LineBasicMaterial({color:'#f2e1b0',transparent:true,opacity:.66,depthTest:false,depthWrite:false}));line.renderOrder=9;group.add(line);
 }
 function flow(link,max){const a=data.marketInfo.get(link.from),b=data.marketInfo.get(link.to),from=[a.center.x,a.center.y],to=[b.center.x,b.center.y],dx=to[0]-from[0],dy=to[1]-from[1],distance=Math.hypot(dx,dy);if(distance<1)return;const nx=-dy/distance,ny=dx/distance,bend=Math.min(70,distance*.13),points=[];
  for(let i=0;i<=40;i++){const t=i/40,bulge=Math.sin(t*Math.PI)*bend;points.push(point(from[0]+dx*t+nx*bulge,from[1]+dy*t+ny*bulge,15));}
  const width=2.5+5*Math.sqrt(link.coins/max),vertices=[],outline=[];for(let i=1;i<points.length;i++){const p=points[i-1],q=points[i],normal=new THREE.Vector3(q.z-p.z,0,p.x-q.x).normalize();for(const [target,w]of [[vertices,width],[outline,width+2.8]]){const v=normal.clone().multiplyScalar(w/2),a=p.clone().add(v),b=p.clone().sub(v),c=q.clone().add(v),d=q.clone().sub(v);target.push(...a.toArray(),...b.toArray(),...c.toArray(),...b.toArray(),...d.toArray(),...c.toArray());}}
  const outlineGeo=new THREE.BufferGeometry();outlineGeo.setAttribute('position',new THREE.Float32BufferAttribute(outline,3));const underlay=new THREE.Mesh(outlineGeo,new THREE.MeshBasicMaterial({color:'#1b363d',transparent:true,opacity:.6,side:THREE.DoubleSide,depthTest:false,depthWrite:false}));underlay.renderOrder=9.5;group.add(underlay);
  const material=new THREE.MeshBasicMaterial({color:a.color,transparent:true,opacity:.94,side:THREE.DoubleSide,depthTest:false,depthWrite:false}),geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));const ribbon=new THREE.Mesh(geo,material);ribbon.renderOrder=10;group.add(ribbon);
  const idx=25,p=points[idx],tangent=points[idx+1].clone().sub(points[idx-1]).normalize(),perp=new THREE.Vector3(tangent.z,0,-tangent.x).multiplyScalar(width*2+2),tip=p.clone().add(tangent.clone().multiplyScalar(10)),base=p.clone().sub(tangent.clone().multiplyScalar(6)),arrowGeo=new THREE.BufferGeometry();arrowGeo.setAttribute('position',new THREE.Float32BufferAttribute([...tip.toArray(),...base.clone().add(perp).toArray(),...base.clone().sub(perp).toArray()],3));const arrow=new THREE.Mesh(arrowGeo,material.clone());arrow.renderOrder=11;group.add(arrow);
  const t=.59,xy=[from[0]+dx*t+nx*Math.sin(t*Math.PI)*bend,from[1]+dy*t+ny*Math.sin(t*Math.PI)*bend];label(xy,`<span>➜ ${compact(link.coins/100)} PO</span>`,'flow',link.coins,()=>onMarket(a.i),`${a.name} → ${b.name} · ${link.trades} transferências`);
 }
 function refresh(next,snapshot){const enabled=['economicMarkets','economicGoods','economicTrade'].includes(next);group.visible=enabled;labels.hidden=!enabled;if(!enabled){mode=next;return;}if(mode===next&&data===snapshot)return;clear();mode=next;data=snapshot;
  if(next==='economicGoods'){boundaries(id=>provinceAt(id)?.i||0);for(const r of data.provinceGoods.values()){if(!r.good||!r.point)continue;const g=snapshot.model.goods.get(r.good);label(r.point,`<i style="background:${r.color}">${esc(goodSymbol(g))}</i><span><b>${esc(g.name)}</b><small>${compact(r.units)} ${esc(g.unit)}</small></span>`,'commodity',r.value,()=>onProvince(r.province.i),`${r.province.name} · bem predominante por valor produzido; outros bens permanecem na ficha`);}}
  else {boundaries(id=>data.marketField[id]);if(next==='economicTrade'){const list=[...data.links.values()].sort((a,b)=>b.coins-a.coins).slice(0,22),max=list[0]?.coins||1;for(const link of list)flow(link,max);}
   for(const m of data.marketInfo.values())label([m.center.x,m.center.y],`<i style="background:${m.color}">⚖</i><span><b>${esc(m.center.name)}</b><small>${compact(m.localValue)} PO · produção${next==='economicTrade'?`<br>↙ ${compact(m.incoming)} · ↗ ${compact(m.outgoing)}`:''}</small></span>`,'market',1e12+m.localValue,()=>onMarket(m.i),`${m.name} · ${m.cities.length} cidades · ${m.states.size} estados · clique para abrir`);
  }
  lastTick=0;tick(performance.now());
 }
 function tick(now){if(labels.hidden||now-lastTick<65)return;lastTick=now;leaders?.replaceChildren();const rects=[],legend=document.querySelector('#economicLegend'),block=legend&&!legend.hidden?legend.getBoundingClientRect():null,distance=camera.position.distanceTo(controls.target),max=distance>1300?30:distance>800?48:75;let shown=0;
  for(const entry of [...entries].sort((a,b)=>b.weight-a.weight)){const {button,anchor,kind}=entry;projected.copy(anchor);projected.y*=relief();projected.project(camera);const x=(projected.x*.5+.5)*innerWidth,y=(-projected.y*.5+.5)*innerHeight,w=kind==='flow'?90:kind==='market'?130:113,h=kind==='market'&&mode==='economicTrade'?62:kind==='flow'?25:42,rect={x:x-w/2,y:y-h/2,w,h};let show=projected.z<1&&projected.z>-1&&x>25&&x<innerWidth-25&&y>170&&y<innerHeight-60&&shown<max;
   let target=rect;if(show){const candidates=kind==='market'?[[0,0],[0,-48],[0,48],[72,0],[-72,0],[72,-45],[-72,45],[145,0],[145,-55],[-145,0]]:[[0,0]];target=null;for(const [dx,dy]of candidates){const c={x:rect.x+dx,y:rect.y+dy,w,h};if(c.x<8||c.x+c.w>innerWidth-8||c.y<155||c.y+c.h>innerHeight-55||rects.some(r=>c.x<r.x+r.w+5&&c.x+c.w+5>r.x&&c.y<r.y+r.h+4&&c.y+c.h+4>r.y)||block&&c.x<block.right&&c.x+c.w>block.left&&c.y<block.bottom&&c.y+c.h>block.top)continue;target=c;break;}show=!!target;}
   button.hidden=!show;if(show){rects.push(target);shown++;button.style.left=(target.x+w/2)+'px';button.style.top=(target.y+h/2)+'px';if(kind==='market'&&(target.x!==rect.x||target.y!==rect.y)){const line=document.createElementNS('http://www.w3.org/2000/svg','line');for(const [name,value]of Object.entries({x1:x,y1:y,x2:target.x+w/2,y2:target.y+h/2}))line.setAttribute(name,value);leaders.append(line);}}}
 }
 return {refresh,tick,group};
}
